import { useCallback } from 'react';
import { useAuth, AUTH_EXPIRED_EVENT } from '../context/AuthContext';
import { todayISO } from '../utils/format';
const SHEET_ID = process.env.REACT_APP_SHEET_ID || 'YOUR_SHEET_ID_HERE';
const ACCOUNTS_SHEET_ID = process.env.REACT_APP_ACCOUNTS_SHEET_ID || SHEET_ID;
const BASE = 'https://sheets.googleapis.com/v4/spreadsheets';

// ── 安全解析可能套了貨幣格式（例如顯示成 "$150"、"($150)"、"-"）的 Sheets 儲存格 ──────
// 2026-10-23 新增：Willie 回報商品總表明明有填成本，App 卻讀不到（算出來都是 $0）。
// 查出來的原因：商品總表的「含稅成本」欄位被套了貨幣格式（儲存格顯示成 "$150" 這樣），
// Google Sheets API 預設的 valueRenderOption 是 FORMATTED_VALUE，這種情況下讀回來的不是
// 數字 150，而是字串 "$150"（這個特定格式的「0」顯示成 "-"）——直接用 Number() 轉換
// 這種字串會變成 NaN，所以之前 readProducts() 算出來的成本永遠是 0，不是代號查無資料，
// 是格式問題讓本來正確的數字變成讀不到。這個函式會先把 $、逗號、括號這些格式符號拿掉，
// 再轉成數字，不管 Sheets 回傳的是原始數字還是套了格式顯示的字串都能正確解析。
// 只用在商品總表/套組成分表/materials 這幾個「人工維護、可能被套用顯示格式」的分頁，
// 其他由 App 自己寫入的平台報表原始資料分頁不會有這個風險，不需要套用。
// ── Google 登入過期偵測（2026-10-25 新增）────────────────────────────────
// Google 的登入憑證大約 1 小時就會過期。之前過期後每一次讀 Sheets 都會失敗，但各個讀取
// 函式都把錯誤吞掉、回傳空陣列，畫面就直接顯示「$0」「尚無資料」——看起來像資料不見了，
// 其實只是登入過期。現在所有對 Google Sheets 的請求都經過 apiFetch，只要收到 401
// （憑證過期/無效），就通知 App 在畫面最上方顯示「登入已過期，請重新登入」的提示。
async function apiFetch(url, opts) {
  const res = await fetch(url, opts);
  if (res.status === 401) {
    try { window.dispatchEvent(new Event(AUTH_EXPIRED_EVENT)); } catch(e) { /* ignore */ }
  }
  return res;
}

// ── 平台原始資料分頁裡「不是資料」的列（2026-10-25 新增）─────────────────
// shopline_raw / momo_raw / shopee_raw / erp_raw 這幾個分頁最上面有 Willie 自己加的
// 標題列（「【每月輸入】…」）、說明列（「📌 …」）、欄名列（「訂單號碼」「客戶代號」…）。
// 之前 readPlatformData 從第2列開始讀、只看第一欄有沒有值，這些列全部被當成銷貨資料，
// 例如欄名列「選項/產品代號」會被當成一個商品代號、出現在銷貨總表/查詢頁裡。
const NON_DATA_FIRST_CELLS = new Set(['訂單號碼', '訂單編號', '客戶代號', '日期', '代號', 'inventory_log']);
function isDataRow(r) {
  const a = String((r && r[0]) || '').trim();
  if (!a) return false;
  if (a.startsWith('【') || a.startsWith('📌') || a.startsWith('⚠')) return false;
  return !NON_DATA_FIRST_CELLS.has(a);
}

// 商品總表 B欄的品牌文字統一成 config.js BRANDS 的 key（TOOLA / LEON / TAKUYA）。
// 商品總表實際填的是「LEONKOSO」，但整個 App（庫存篩選按鈕、品牌損益）用的是「LEON」，
// 之前兩邊對不起來，庫存管理按「麗容酵素」篩選會一筆都看不到。
function normalizeBrand(raw, code) {
  const b = String(raw || '').trim().toUpperCase().replace(/\s+/g, '');
  if (b.startsWith('LEON') || b.includes('麗容')) return 'LEON';
  if (b.startsWith('TOOLA') || b.includes('多樂')) return 'TOOLA';
  if (b.startsWith('TAKUYA') || b.includes('拓屋')) return 'TAKUYA';
  const c = String(code || '').toUpperCase();
  if (c.startsWith('BDLN')) return 'LEON';
  if (c.startsWith('BDTL')) return 'TOOLA';
  return 'TAKUYA';
}

function parseMoney(v) {
  if (v === null || v === undefined || v === '') return 0;
  if (typeof v === 'number') return v;
  const s = String(v).trim();
  if (s === '' || s === '-' || s === '–' || s === '—') return 0;
  const negative = /^\(.*\)$/.test(s);
  const cleaned = s.replace(/[^0-9.-]/g, '');
  let num = Number(cleaned);
  if (isNaN(num)) return 0;
  if (negative && num > 0) num = -num;
  return num;
}

export function useSheets() {
  const { token } = useAuth();
  const hdrs = useCallback(() => ({
    'Content-Type': 'application/json',
    Authorization: `Bearer ${token}`
  }), [token]);

  // 注意：這裡一定要強制不快取，不然開單/上傳報表寫入 Sheets 後馬上切回銷貨總表
  // 或重新整理頁面，剛剛寫入的那筆資料會看不到（寫入本身是成功的，是瀏覽器把
  // 「讀取」這個 GET 請求的結果快取住了，沒有真的重新跟 Google 要最新資料）。
  //
  // ⚠ 2026-09-26 重大修正：之前這裡是在網址後面加一個自訂的 `?_ts=時間戳記` 參數
  // 來讓每次讀取的網址都不一樣、騙過瀏覽器快取。這個寫法本來可以動，但 Google
  // Sheets API 後來開始嚴格檢查網址上的參數，只要出現一個 API 不認識的參數
  // （像 `_ts`），現在會直接回傳 400 錯誤（"Unknown name \"_ts\": Cannot bind
  // query parameter"），等於「每一次」讀取 Sheets 都會失敗——這就是 9/26 Willie
  // 回報「所有資料都不見了」的真正原因：不是 Sheets 裡的資料被清空，是網站每一次
  // 想要讀資料都被 Google 擋掉，畫面上當然什麼都看不到。已改成只靠 `cache:'no-store'`
  // 這個 fetch 本身的設定去強制不快取，不再加這個會被 Google 擋掉的網址參數。
  const read = useCallback(async (range) => {
    const url = `${BASE}/${SHEET_ID}/values/${encodeURIComponent(range)}`;
    const res = await apiFetch(url, { headers: hdrs(), cache: 'no-store' });
    if (!res.ok) throw new Error(`Sheets read error: ${res.status}`);
    return (await res.json()).values || [];
  }, [hdrs]);

  const append = useCallback(async (range, values) => {
    const url = `${BASE}/${SHEET_ID}/values/${encodeURIComponent(range)}:append?valueInputOption=USER_ENTERED`;
    const res = await apiFetch(url, {
      method: 'POST',
      headers: hdrs(),
      body: JSON.stringify({ range, majorDimension: 'ROWS', values }),
    });
    if (!res.ok) {
      const errText = await res.text().catch(() => '');
      throw new Error(`Sheets append error: ${res.status} ${errText}`);
    }
    return res.json();
  }, [hdrs]);

  // 跟 append() 一樣，差別是用 valueInputOption=RAW：Google Sheets 完全不會去「猜」
  // 這個字串是不是日期/數字，一律照字面存成文字。目前只有 savePnlData 在用——
  // 核對後發現用一般的 append()（USER_ENTERED）存「2026-07」這種年月字串時，
  // Google Sheets 會自動把它解讀成日期（存成 2026-07-01，再套用「yyyy-mm」格式讓它
  // 顯示/讀回來還是「2026-07」這個字串，所以目前還不算真的讀錯），但這是巧合不是保證，
  // 換成 RAW 直接從根源避免這種「看起來沒事、但其實存成別的型態」的情況。
  const appendRaw = useCallback(async (range, values) => {
    const url = `${BASE}/${SHEET_ID}/values/${encodeURIComponent(range)}:append?valueInputOption=RAW`;
    const res = await apiFetch(url, {
      method: 'POST',
      headers: hdrs(),
      body: JSON.stringify({ range, majorDimension: 'ROWS', values }),
    });
    if (!res.ok) {
      const errText = await res.text().catch(() => '');
      throw new Error(`Sheets append error: ${res.status} ${errText}`);
    }
    return res.json();
  }, [hdrs]);

  // ── 自動補建缺少的分頁（2026-10-22 新增）──────────────────────
  // savePnlData（存進 pnl_expenses）之類的功能，如果 Willie 還沒手動建立對應的分頁，
  // 寫入會失敗（Sheets API 找不到這個分頁名稱，回傳 400 "Unable to parse range"）。
  // 之前只能請 Willie 自己先手動建好分頁，但這一步很容易忘記——10/11 的版本就真的
  // 發生過：部署了新版但忘記先建「pnl_expenses」分頁，導致那個月的費用沒存成功。
  // 現在改成：寫入失敗時，先檢查是不是「分頁不存在」造成的（不是其他原因，例如
  // 權限不足或網路問題），是的話就呼叫 Sheets API 自動補建一個同名的空分頁，
  // 再重試一次原本的寫入，Willie 不需要再自己手動先建分頁。
  const ensureSheetTab = useCallback(async (sheetName) => {
    const res = await apiFetch(`${BASE}/${SHEET_ID}:batchUpdate`, {
      method: 'POST',
      headers: hdrs(),
      body: JSON.stringify({ requests: [{ addSheet: { properties: { title: sheetName } } }] }),
    });
    if (!res.ok) {
      const errText = await res.text().catch(() => '');
      // 如果是因為分頁「已經存在」才失敗（例如剛好跟別的操作同時觸發，或已經手動建好），
      // 不算真的錯誤，直接當成功處理——分頁本來就在，不需要再補建。
      if (errText.includes('already exists')) return;
      throw new Error(`Sheets 自動建立分頁「${sheetName}」失敗：${res.status} ${errText}`);
    }
  }, [hdrs]);

  // 包一層：寫入時如果發現是「分頁不存在」造成的 400 錯誤，自動補建分頁後重試一次。
  // 其他原因造成的錯誤（例如權限不足、網路問題）則照原樣往外丟，不會被這裡吞掉，
  // 畫面上還是會看到真正的錯誤訊息。
  const appendRawEnsureSheet = useCallback(async (sheetName, range, values) => {
    try {
      return await appendRaw(range, values);
    } catch (e) {
      if (/Unable to parse range/i.test(e.message)) {
        await ensureSheetTab(sheetName);
        return await appendRaw(range, values);
      }
      throw e;
    }
  }, [appendRaw, ensureSheetTab]);

  const clear = useCallback(async (range) => {
    const res = await apiFetch(`${BASE}/${SHEET_ID}/values/${encodeURIComponent(range)}:clear`,
      { method: 'POST', headers: hdrs() });
    if (!res.ok) throw new Error(`Sheets clear error: ${res.status}`);
    return res.json();
  }, [hdrs]);

  // ── 真的刪除整列（2026-10-25 新增，手動開單「刪除/修改」用）──────────────
  // 刻意不用「清空內容」(values:clear)：清空後中間會留下空白列，而 writeOrder 用的
  // append 會從 A1 往下找「表格的最後一列」接著寫——遇到中間有空白列時，Google 可能把
  // 新資料寫進那個空白洞裡，品項多於空白列數時甚至會蓋掉下面原本的訂單。
  // 所以這裡改成用 batchUpdate 的 deleteDimension 把整列真的刪掉，表格永遠保持連續。
  // deleteDimension 需要分頁的數字 sheetId（不是分頁名稱），先查一次。
  const getSheetNumericId = useCallback(async (title) => {
    const res = await apiFetch(`${BASE}/${SHEET_ID}?fields=sheets.properties(sheetId,title)`,
      { headers: hdrs(), cache: 'no-store' });
    if (!res.ok) throw new Error(`讀取分頁資訊失敗：${res.status}`);
    const data = await res.json();
    const sh = (data.sheets || []).find(x => x.properties?.title === title);
    if (!sh) throw new Error(`找不到分頁「${title}」`);
    return sh.properties.sheetId;
  }, [hdrs]);

  // rowNumbers：試算表上的列號（從1開始算，第1列是表頭）。
  // 由下往上刪：先刪下面的列，上面還沒刪的列號才不會因為「下面補上來」而跑掉。
  const deleteSheetRows = useCallback(async (title, rowNumbers) => {
    if (!rowNumbers || rowNumbers.length === 0) return;
    const sheetId = await getSheetNumericId(title);
    const sorted = [...new Set(rowNumbers)].sort((a, b) => b - a);
    const requests = sorted.map(n => ({
      deleteDimension: { range: { sheetId, dimension: 'ROWS', startIndex: n - 1, endIndex: n } },
    }));
    const res = await apiFetch(`${BASE}/${SHEET_ID}:batchUpdate`, {
      method: 'POST', headers: hdrs(), body: JSON.stringify({ requests }),
    });
    if (!res.ok) {
      const errText = await res.text().catch(() => '');
      throw new Error(`刪除列失敗：${res.status} ${errText}`);
    }
  }, [hdrs, getSheetNumericId]);

  const writePlatformData = useCallback(async (platformOrSheet, rows) => {
    const map = {
      'shopline_raw': 'shopline_raw',
      'momo_raw': 'momo_raw',
      'shopee_raw': 'shopee_raw',
      'erp_raw': 'erp_raw',
      'TOOLA_SHOPLINE': 'shopline_raw',
      'TOOLA_SHOPEE': 'shopee_raw',
      'TAKUYA_SHOPLINE': 'shopline_raw',
      'TAKUYA_SHOPEE': 'shopee_raw',
      'MOMO': 'momo_raw',
      'ERP': 'erp_raw',
      'momo': 'momo_raw',
      'shopee': 'shopee_raw',
      'shopline': 'shopline_raw',
      'erp': 'erp_raw',
    };
    const sheet = map[platformOrSheet] || platformOrSheet;
    if (!sheet) throw new Error(`Unknown sheet: ${platformOrSheet}`);
    if (rows.length > 0) {
      const cleanRows = rows.map(row =>
        (Array.isArray(row) ? row : Object.values(row)).map(v =>
          v === null || v === undefined ? '' : String(v)
        )
      );
      await append(sheet, cleanRows);
    }
    return rows.length;
  }, [append]);

  const readExpenses = useCallback(async () => {
    try {
      const rows = await read('expenses!A5:C60');
      const expenses = {};
      rows.forEach(r => { if (r[0] && r[2] && !isNaN(Number(r[2]))) expenses[r[0]] = Number(r[2]); });
      return expenses;
    } catch { return {}; }
  }, [read]);

  const writeExpenses = useCallback(async (expenseMap) => {
    try {
      const rows = await read('expenses!A5:A60');
      const updates = rows.map((r, i) =>
        r[0] && expenseMap[r[0]] !== undefined
          ? { range: `expenses!C${5+i}`, values: [[expenseMap[r[0]]]] } : null
      ).filter(Boolean);
      if (!updates.length) return;
      await apiFetch(`${BASE}/${SHEET_ID}/values:batchUpdate`, {
        method: 'POST', headers: hdrs(),
        body: JSON.stringify({ valueInputOption: 'USER_ENTERED', data: updates }),
      });
    } catch { /* demo mode */ }
  }, [read, hdrs]);

  // 從 Google Sheets 讀取客戶資料
  const readCustomers = useCallback(async () => {
    try {
      // N欄（發票地址）是新增的欄位，跟 A~M 的「主要配送地址」是分開的兩個地址——
      // 客戶管理頁之前只有配送地址，Willie 反映發票地址跟配送地址可能不一樣，需要分開填。
      const rows = await read('customers!A2:N');
      return rows.filter(r => r[0]).map(r => ({
        code:         r[0] || '',
        name:         r[1] || '',
        shortName:    r[2] || '',
        invoiceTitle: r[3] || '',
        taxId:        r[4] || '',
        phone:        r[5] || '',
        fax:          r[6] || '',
        address:      r[7] || '',
        contact:      r[8] || '',
        ext:          r[9] || '',
        email:        r[10] || '',
        mobile:       r[11] || '',
        note:         r[12] || '',
        invoiceAddress: r[13] || '',
        id:           r[0] || '',
        type:         'DEALER',
        orders:       [],
        totalAmount:  0,
        lastOrderDate: null,
        active:       true,
      }));
    } catch(e) { return []; }
  }, [read]);

  // 寫入新客戶到 Sheets
  const writeCustomer = useCallback(async (customer) => {
    const row = [
      customer.code || customer.id,
      customer.name, customer.shortName || '',
      customer.invoiceTitle || '', customer.taxId || '',
      customer.phone || '', customer.fax || '',
      customer.address || '', customer.contact || '',
      customer.ext || '', customer.email || '',
      customer.mobile || '', customer.note || '',
      customer.invoiceAddress || '', // N: 發票地址
    ];
    await append('customers!A1', [row]);
  }, [append]);

  // 修改既有客戶資料並寫回 Sheets（同 updateAccount 的做法：先找到那一列，整列覆寫）
  // 之前 CRM 頁面的新增/編輯完全沒有呼叫任何 Sheets 寫入，全部只存在瀏覽器記憶體裡，
  // 重新整理或別人登入就會不見，這裡補上真正的同步。
  const updateCustomer = useCallback(async (code, updates) => {
    try {
      const rows = await readCustomers();
      const idx = rows.findIndex(r => r.code === code);
      if (idx === -1) {
        return { ok:false, error:`在 Sheets 的客戶清單裡找不到 ${code}，這筆修改沒有同步（可能當初新增客戶時就沒有寫入成功）` };
      }
      const sheetRow = idx + 2; // header 在第 1 列，資料從第 2 列開始
      const customer = { ...rows[idx], ...updates };
      const row = [
        customer.code || code,
        customer.name || '', customer.shortName || '',
        customer.invoiceTitle || '', customer.taxId || '',
        customer.phone || '', customer.fax || '',
        customer.address || '', customer.contact || '',
        customer.ext || '', customer.email || '',
        customer.mobile || '', customer.note || '',
        customer.invoiceAddress || '', // N: 發票地址
      ];
      const url = `${BASE}/${SHEET_ID}/values/${encodeURIComponent(`customers!A${sheetRow}`)}?valueInputOption=USER_ENTERED`;
      const res = await apiFetch(url, {
        method: 'PUT', headers: hdrs(),
        body: JSON.stringify({ range: `customers!A${sheetRow}`, majorDimension: 'ROWS', values: [row] }),
      });
      if (!res.ok) {
        const err = await res.text().catch(()=>'');
        console.warn('updateCustomer failed:', res.status, err);
        return { ok:false, error:`寫入 Google Sheets 失敗（${res.status}），這筆客戶修改沒有同步` };
      }
      return { ok:true };
    } catch(e) {
      console.warn('updateCustomer error:', e.message);
      return { ok:false, error:`寫入 Google Sheets 失敗：${e.message}，這筆客戶修改沒有同步` };
    }
  }, [hdrs, readCustomers]);

  // 寫入手動開單到 orders 頁籤（每個品項一列）
  const writeOrder = useCallback(async (order) => {
    const rows = order.items.map(item => [
      order.id,
      order.date,
      order.channel,
      order.customerId || '',
      order.customer || '',
      order.dealerShort || '',
      order.dealerTaxId || '',
      order.dealerTitle || '',
      item.code || '',
      item.name || '',
      item.qty || 0,
      item.price || 0,
      (item.qty || 0) * (item.price || 0),
      order.taxType === 'taxed'
        ? (item.qty || 0) * (item.price || 0)
        : Math.round((item.qty || 0) * (item.price || 0) * 1.05),
      order.taxType === 'taxed'
        ? Math.round((item.qty || 0) * (item.price || 0) / 1.05 * 0.05)
        : Math.round((item.qty || 0) * (item.price || 0) * 0.05),
      order.note || '',
    ]);
    await append('orders!A1', rows);
    return rows.length;
  }, [append]);

  // 讀取開單紀錄
  // ⚠ 2026-10-22 修正欄位命名：原本 taxAmount/tax 這兩個欄位的名字跟實際存的內容是反的——
  // 「taxAmount」聽起來應該是「稅額」本身，但原本接的是 r[13]（N欄「含稅金額」，是稅後的總額，
  // 不是稅額）；「tax」接的才是 r[14]（O欄「稅額」，真正的稅金）。命名跟實際內容對不起來，
  // 容易造成以後接這個函式的人算錯（這個函式目前沒有任何畫面在呼叫，是備用的讀取功能，
  // 但既然要修稅務欄位就一併把命名改正確，避免以後真的拿來用時出錯）。
  const readOrders = useCallback(async () => {
    try {
      const rows = await read('orders!A2:P');
      return rows.filter(r => r[0]).map(r => ({
        id:           r[0] || '',
        date:         r[1] || '',
        channel:      r[2] || '',
        customerId:   r[3] || '',
        customer:     r[4] || '',
        dealerShort:  r[5] || '',
        dealerTaxId:  r[6] || '',
        dealerTitle:  r[7] || '',
        code:         r[8] || '',
        name:         r[9] || '',
        qty:          Number(r[10]) || 0,
        price:        Number(r[11]) || 0,
        subtotal:     Number(r[12]) || 0,  // M: 小計（單價×數量，未套用稅）
        taxedTotal:   Number(r[13]) || 0,  // N: 含稅金額（稅後總額——跟其他平台的「營收」基礎一致）
        taxAmount:    Number(r[14]) || 0,  // O: 稅額（稅金本身）
        note:         r[15] || '',
      }));
    } catch(e) { return []; }
  }, [read]);

  // ── 手動開單：讀取全部歷史訂單（依訂單編號組回整張訂單）（2026-10-25 新增）──────
  // Willie 回報問題1：手動開單頁的訂單列表，之前只存在瀏覽器「這次打開頁面」的記憶體裡，
  // 從來沒有讀過 Google Sheets 的歷史訂單——重新整理頁面就整組清空，也沒辦法點擊編輯/刪除。
  // 這裡改成真的從 orders 分頁讀取「全部歷史訂單」（Willie 確認範圍是全部，不只本月）。
  // writeOrder 是「一個品項存一列」，同一張訂單的多個品項共用同一個訂單編號，所以這裡要
  // 把同編號的列重新組回一張完整的訂單（包含 items 陣列），畫面才能整張顯示/編輯/刪除。
  //
  // 含稅/未稅：orders 分頁沒有直接存「開單時選哪一種」，但可以從存下來的數字反推——
  // writeOrder 存的 M欄「小計」= 單價×數量；選「含稅」時 N欄含稅金額 = 小計，
  // 選「未稅」時 N欄 = 小計×1.05。所以整張單 N 加總等於 M 加總就是含稅，否則是未稅。
  // （一定要反推正確：如果未稅的單被當成含稅載入再存檔，含稅金額會少掉5%。）
  // 金額欄位用 parseMoney 讀，避免 Sheets 套了千分位/貨幣格式時被讀成 0。
  const readOrdersGrouped = useCallback(async () => {
    const rows = await read('orders!A2:P'); // 失敗直接往外丟，讓畫面顯示「讀取失敗」而不是「沒有訂單」
    const groups = new Map();
    rows.forEach((r, i) => {
      const id = String(r[0] || '').trim();
      if (!id) return;
      if (!groups.has(id)) {
        groups.set(id, {
          id,
          date:        r[1] || '',
          channel:     r[2] || '',
          customerId:  r[3] || '',
          customer:    r[4] || '',
          dealerShort: r[5] || '',
          dealerTaxId: r[6] || '',
          dealerTitle: r[7] || '',
          note:        r[15] || '',
          sumM: 0, taxedTotal: 0, taxAmount: 0,
          rowOrder: i,
          items: [],
        });
      }
      const g = groups.get(id);
      g.items.push({
        code:  r[8] || '',
        name:  r[9] || '',
        qty:   parseMoney(r[10]),
        price: parseMoney(r[11]),
      });
      g.sumM       += parseMoney(r[12]);
      g.taxedTotal += parseMoney(r[13]); // N: 含稅金額（跟銷貨總表/損益表的營收基礎一致）
      g.taxAmount  += parseMoney(r[14]);
      g.rowOrder = Math.max(g.rowOrder, i);
    });
    return Array.from(groups.values())
      .map(o => {
        const subtotal = o.items.reduce((s, it) => s + it.price * it.qty, 0);
        const taxType = Math.abs(o.taxedTotal - o.sumM) < 1 ? 'taxed' : 'untaxed';
        const { sumM, ...rest } = o;
        return { ...rest, subtotal, taxType };
      })
      .sort((a, b) => String(b.date).localeCompare(String(a.date)) || b.rowOrder - a.rowOrder);
  }, [read]);

  // 找出 orders 分頁裡屬於某張訂單（同一個訂單編號）的所有列號（試算表列號，從1開始）
  const findOrderRowNumbers = useCallback(async (orderId) => {
    const rows = await read('orders!A2:P');
    const nums = [];
    rows.forEach((r, i) => { if (String(r[0] || '').trim() === orderId) nums.push(i + 2); });
    return nums;
  }, [read]);

  // 刪除一張訂單：把它在 orders 分頁佔用的所有品項列整列刪掉
  const deleteOrder = useCallback(async (orderId) => {
    try {
      const nums = await findOrderRowNumbers(orderId);
      if (nums.length === 0) {
        return { ok:false, error:`在 Google Sheets 的 orders 分頁裡找不到訂單 ${orderId}（可能已經被刪除，或當初沒有同步成功）` };
      }
      await deleteSheetRows('orders', nums);
      return { ok:true };
    } catch(e) {
      console.warn('deleteOrder failed:', e.message);
      return { ok:false, error:`刪除失敗：${e.message}` };
    }
  }, [findOrderRowNumbers, deleteSheetRows]);

  // 修改一張既有訂單：先把修改後的內容寫到 orders 分頁最後面（訂單編號不變），
  // 寫入成功後才刪掉原本那幾列。不直接覆寫原來的列，是因為修改後品項數量可能跟
  // 原本不一樣（新增/刪掉品項），原地覆寫沒辦法處理列數變多/變少。
  // 順序是「先寫新的、成功後才刪舊的」：萬一寫入失敗，原本的訂單還完整保留。
  // 新資料是接在表格最後面，不會影響上面舊列的列號，所以先查好的舊列號刪除時仍然正確。
  const updateOrder = useCallback(async (orderId, newOrder) => {
    let wrote = false;
    try {
      const oldNums = await findOrderRowNumbers(orderId);
      await writeOrder({ ...newOrder, id: orderId });
      wrote = true;
      if (oldNums.length > 0) await deleteSheetRows('orders', oldNums);
      return { ok:true };
    } catch(e) {
      console.warn('updateOrder failed:', e.message);
      return { ok:false, error: wrote
        ? `修改後的內容已經存進去了，但原本那份沒刪掉（${e.message}），這張訂單的品項現在會重複出現（金額會變成兩倍），請到 Google Sheets 的 orders 分頁把這個訂單編號比較上面的那幾列刪掉，或截圖這則訊息給管理員。`
        : `修改失敗：${e.message}。原本的訂單沒有被動到。` };
    }
  }, [findOrderRowNumbers, deleteSheetRows, writeOrder]);

  // 更新商品總表庫存欄位（H欄=現有庫存, J欄=上次入庫日期）
  // 回傳 { ok, error } 而不是直接吞掉錯誤，讓畫面上可以告訴使用者「有沒有真的寫進 Sheets」
  const updateInventory = useCallback(async (code, newStock, oldStock, type, qty, operator, note) => {
    try {
      // 1. 寫入 inventory_log
      // 日期改用 YYYY-MM-DD（todayISO()），不要再用 toLocaleDateString('zh-TW')——
      // 後者格式是「2026/9/23」，跟銷貨/入庫查詢頁 <input type="date"> 篩選比對的格式對不起來，
      // 會造成用日期區間查詢入庫紀錄時查不到任何資料（詳見 utils/format.js 的說明）。
      const logRow = [
        todayISO(),
        type || '入庫',
        code, '', qty, oldStock, newStock, note || '', operator || '',
      ];
      await append('inventory_log!A3', [logRow]);

      // 2. 讀取商品總表找到對應列
      const rows = await read('商品總表!A4:L');
      const rowIdx = rows.findIndex(r => String(r[0]).trim() === String(code).trim());
      if (rowIdx === -1) {
        console.warn('Product not found in Sheets:', code);
        return { ok:false, error:`商品代號 ${code} 在 Sheets 的「商品總表」裡找不到，庫存沒有同步` };
      }
      const sheetRow = rowIdx + 4; // 資料從第4列開始

      // 3. 更新庫存欄位（H欄=現有庫存, J欄=上次入庫, K欄=上次盤點）
      // 注意：I欄（安全庫存）絕對不能跟其他欄位放在同一個連續範圍一起寫，
      // 即使值填''打算「不動」，Google Sheets 批次更新還是會把範圍內每一格都覆蓋成那個值，
      // 等於把安全庫存實際清空成空白——這就是之前「盤點後安全庫存變0、畫面上又顯示成預設50」的原因。
      // 修正方式：安全庫存欄位整個不出現在要更新的範圍裡，Google Sheets 才不會去動它。
      // 同理，J（上次入庫日期）跟K（上次盤點日期）也分開各自獨立更新，
      // 不要用不相關的那一次操作把另一個欄位覆蓋成空白。
      const today = new Date().toLocaleDateString('zh-TW');
      const updates = [
        { range: `商品總表!H${sheetRow}`, values: [[newStock]] },
        type !== '盤點'
          ? { range: `商品總表!J${sheetRow}`, values: [[today]] }
          : { range: `商品總表!K${sheetRow}`, values: [[today]] },
      ];
      const batchRes = await apiFetch(`${BASE}/${SHEET_ID}/values:batchUpdate`, {
        method: 'POST', headers: hdrs(),
        body: JSON.stringify({ valueInputOption: 'USER_ENTERED', data: updates }),
      });
      if (!batchRes.ok) {
        const err = await batchRes.text().catch(()=>'');
        console.warn('batchUpdate failed:', batchRes.status, err);
        return { ok:false, error:`寫入 Google Sheets 失敗（${batchRes.status}），庫存只更新在畫面上，請截圖回報管理員` };
      }
      return { ok:true };
    } catch(e) {
      console.warn('updateInventory failed:', e.message);
      return { ok:false, error:`寫入 Google Sheets 失敗：${e.message}，庫存只更新在畫面上，請截圖回報管理員` };
    }
  }, [read, append, hdrs]);

  // 新增商品到商品總表
  const writeNewProduct = useCallback(async (product) => {
    const row = [
      product.code,           // A: 原始代號
      product.brand || '',    // B: 品牌（新增）
      product.name,           // C: 品名規格
      '',                     // D: Bar Code
      product.u || 1,         // E: 單組數量
      product.cost || 0,      // F: 含稅成本
      '',                     // G: 未稅成本
      product.stock || 0,     // H: 現有庫存
      product.safety || 50,   // I: 安全庫存
      '',                     // J: 上次入庫日期
      '',                     // K: 上次盤點日期
      product.note || '',     // L: 備註
    ];
    await append('商品總表!A1', [row]);
  }, [append]);


  // ── 帳號管理（獨立試算表）────────────────────────────────────
  const readAccounts = useCallback(async () => {
    try {
      // 同上（見 read() 的說明）：拿掉會被 Google Sheets API 擋掉的 `_ts` 網址參數，
      // 改靠 cache:'no-store' 強制不快取。
      const url = `${BASE}/${ACCOUNTS_SHEET_ID}/values/${encodeURIComponent('accounts!A2:G')}`;
      const res = await apiFetch(url, { headers: hdrs(), cache: 'no-store' });
      if (!res.ok) return [];
      const rows = (await res.json()).values || [];
      return rows.filter(r => r[0]).map(r => ({
        email:     r[0] || '',
        name:      r[1] || '',
        role:      r[2] || 'viewer',
        perms:     r[3] ? r[3].split(',').map(p => p.trim()) : ['VIEW_ALL'],
        active:    (r[4] || '啟用') === '啟用',
        createdAt: r[5] || '',
        note:      r[6] || '',
      }));
    } catch(e) { console.warn('readAccounts error:', e.message); return []; }
  }, [hdrs]);

  const writeAccount = useCallback(async (account) => {
    const row = [
      account.email,
      account.name || '',
      account.role || 'viewer',
      (account.perms || ['VIEW_ALL']).join(','),
      account.active !== false ? '啟用' : '停用',
      account.createdAt || new Date().toLocaleDateString('zh-TW'),
      account.note || '',
    ];
    const url = `${BASE}/${ACCOUNTS_SHEET_ID}/values/${encodeURIComponent('accounts!A1')}:append?valueInputOption=USER_ENTERED`;
    const res = await apiFetch(url, {
      method: 'POST', headers: hdrs(),
      body: JSON.stringify({ range: 'accounts!A1', majorDimension: 'ROWS', values: [row] }),
    });
    if (!res.ok) throw new Error(`writeAccount error: ${res.status}`);
    return res.json();
  }, [hdrs]);

  // 回傳 { ok, error } 而不是吞掉錯誤 —
  // 這裡以前失敗會完全沒提示，導致管理者以為改好了同事的權限，其實 Sheets 裡完全沒變，
  // 同事下次登入讀到的還是舊權限。
  const updateAccount = useCallback(async (email, updates) => {
    try {
      const rows = await readAccounts();
      const idx = rows.findIndex(r => r.email?.toLowerCase() === email?.toLowerCase());
      if (idx === -1) {
        return { ok:false, error:`在 Sheets 的帳號清單裡找不到 ${email}，權限沒有同步（可能當初新增帳號時就沒有寫入成功）` };
      }
      const sheetRow = idx + 2; // header at row 1, data from row 2
      const account = { ...rows[idx], ...updates };
      const row = [
        account.email,
        account.name || '',
        account.role || 'viewer',
        (account.perms || ['VIEW_ALL']).join(','),
        account.active !== false ? '啟用' : '停用',
        account.createdAt || '',
        account.note || '',
      ];
      const url = `${BASE}/${ACCOUNTS_SHEET_ID}/values/${encodeURIComponent(`accounts!A${sheetRow}`)}?valueInputOption=USER_ENTERED`;
      const res = await apiFetch(url, {
        method: 'PUT', headers: hdrs(),
        body: JSON.stringify({ range: `accounts!A${sheetRow}`, majorDimension: 'ROWS', values: [row] }),
      });
      if (!res.ok) {
        const err = await res.text().catch(()=>'');
        console.warn('updateAccount failed:', res.status, err);
        return { ok:false, error:`寫入 Google Sheets 失敗（${res.status}），權限沒有同步` };
      }
      return { ok:true };
    } catch(e) {
      console.warn('updateAccount error:', e.message);
      return { ok:false, error:`寫入 Google Sheets 失敗：${e.message}，權限沒有同步` };
    }
  }, [hdrs, readAccounts]);

  // ── 耗材/包材庫存（materials 分頁：第1列標題、第2列欄名、資料從第3列開始）─────
  const readMaterials = useCallback(async () => {
    try {
      const rows = await read('materials!A3:K');
      return rows.filter(r => r[0]).map(r => ({
        code:       r[0] || '',
        name:       r[1] || '',
        size:       r[2] || '',
        unit:       r[3] || '',
        forProduct: r[4] || '',
        stock:      Number(r[5]) || 0,
        safety:     Number(r[6]) || 0,
        cost:       parseMoney(r[7]), // 跟商品總表一樣，成本欄可能被套了貨幣格式，見 parseMoney 說明
        vendor:     r[8] || '',
        vendorTel:  r[9] || '',
        note:       r[10] || '',
      }));
    } catch(e) { console.warn('readMaterials error:', e.message); return []; }
  }, [read]);

  const writeMaterial = useCallback(async (material) => {
    const row = [
      material.code, material.name || '', material.size || '',
      material.unit || '', material.forProduct || '',
      material.stock || 0, material.safety || 0, material.cost || 0,
      material.vendor || '', material.vendorTel || '', material.note || '',
    ];
    await append('materials!A1', [row]);
  }, [append]);

  // 回傳 { ok, error } 而不是吞掉錯誤，跟商品/帳號/客戶的做法一致 ——
  // 之前耗材庫存完全沒有寫入 Sheets 的動作，這裡補上真正的同步。
  const updateMaterial = useCallback(async (code, newStock) => {
    try {
      const rows = await readMaterials();
      const idx = rows.findIndex(r => r.code === code);
      if (idx === -1) {
        return { ok:false, error:`在 Sheets 的 materials 分頁裡找不到 ${code}，庫存沒有同步（可能當初新增耗材時就沒有寫入成功）` };
      }
      const sheetRow = idx + 3; // 第1列標題、第2列欄名，資料從第3列開始
      const url = `${BASE}/${SHEET_ID}/values/${encodeURIComponent(`materials!F${sheetRow}`)}?valueInputOption=USER_ENTERED`;
      const res = await apiFetch(url, {
        method: 'PUT', headers: hdrs(),
        body: JSON.stringify({ range: `materials!F${sheetRow}`, majorDimension: 'ROWS', values: [[newStock]] }),
      });
      if (!res.ok) {
        const err = await res.text().catch(()=>'');
        console.warn('updateMaterial failed:', res.status, err);
        return { ok:false, error:`寫入 Google Sheets 失敗（${res.status}），耗材庫存只更新在畫面上，請截圖回報管理員` };
      }
      return { ok:true };
    } catch(e) {
      console.warn('updateMaterial error:', e.message);
      return { ok:false, error:`寫入 Google Sheets 失敗：${e.message}，耗材庫存只更新在畫面上，請截圖回報管理員` };
    }
  }, [hdrs, readMaterials]);

  // ── 從 Sheets 讀取商品清單 ──────────────────────────────────
  // 注意：商品總表的「含稅成本」（F欄）只有單品（單組數量=1）會手動填寫；
  // 套組/多入組代號（例如「2入組」「3入組」）在商品總表裡成本欄是空白的，
  // 真正的成本要看套組成分表換算加總（一個套組可能由多列成分組成，即混合套組），
  // 所以這裡會一併讀套組成分表，把換算後的成本蓋掉商品總表裡那個空白（等於0）的值，
  // 這樣不管是首頁、損益表、銷貨總表、庫存資產、手動開單，只要是呼叫 readProducts()，
  // 拿到的每個代號成本都已經是正確的，不用個別頁面自己處理套組換算。
  // ⚠ 2026-10-23 修正：F欄（含稅成本）改用 parseMoney() 解析，不要直接用 Number()
  // ——Willie 把這欄套了貨幣顯示格式（"$150" 這樣），Sheets API 預設讀回來的是這種
  // 格式化後的字串，Number() 轉換會變成 NaN、全部的成本都被當成 0（詳見上方
  // parseMoney 的說明），不是真的代號查無資料。
  const readProducts = useCallback(async () => {
    try {
      const [rows, bundleRows] = await Promise.all([
        read('商品總表!A4:L'),
        read('套組成分表!A4:F').catch(() => []),
      ]);
      const bundleCost = {};
      const bundleComponents = {}; // 2026-10-23 新增：記錄每個套組代號由哪些成分組成（補品名用）
      (bundleRows || []).forEach(r => {
        const bundleCode = String(r[0] || '').trim();
        if (!bundleCode) return;
        bundleCost[bundleCode] = (bundleCost[bundleCode] || 0) + parseMoney(r[5]); // F: 成分含稅成本
        const compCode = String(r[2] || '').trim(); // C: 成分單品代號
        const compName = String(r[3] || '').trim(); // D: 成分單品品名(自動帶入)
        const compQty  = parseMoney(r[4]);          // E: 每組含量
        if (compCode || compName) {
          if (!bundleComponents[bundleCode]) bundleComponents[bundleCode] = [];
          bundleComponents[bundleCode].push({ code: compCode, name: compName, qty: compQty });
        }
      });
      const existingCodes = new Set();
      const products = rows
        .filter(r => r[0] && String(r[0]).trim() !== '')
        .map(r => {
          const code  = String(r[0]).trim();
          existingCodes.add(code);
          const brand = normalizeBrand(r[1], code); // B欄品牌（統一成 TOOLA / LEON / TAKUYA，見 normalizeBrand 說明）
          const baseCost = parseMoney(r[5]); // F: 含稅成本（單品才會手動填；可能是貨幣格式字串）
          const cost = Object.prototype.hasOwnProperty.call(bundleCost, code) ? bundleCost[code] : baseCost;
          return {
            code,
            brand,
            name:    r[2] || '',   // C: 品名規格
            barcode: r[3] || '',   // D: Bar Code
            u:       Number(r[4]) || 1,    // E: 單組數量
            cost,
            stock:   parseMoney(r[7]),     // H: 現有庫存
            safety:  Number(r[8]) || 50,   // I: 安全庫存
            sold:    0,
            components: bundleComponents[code] || null, // 套組/多入組才有：[{code,name,qty}]，銷貨總表「單品換算」用
          };
        });

      // ⚠ 2026-10-23 新增：套組成分表裡有建好成分換算、但商品總表完全沒有那一列的「套組/多入組代號」
      // ——之前的邏輯是先讀商品總表的列，再用套組成分表的換算成本去「蓋掉」同代號那一列的空白成本；
      // 如果商品總表根本沒有建這個代號的列，這個代號就完全不會出現在回傳的商品清單裡，costMap 查不到，
      // 銷貨總表/損益表/首頁就會顯示「查無成本資料」（畫面上會誤以為兩邊都沒資料，但其實套組成分表
      // 已經有建好換算）。這裡補上：商品總表沒有、但套組成分表有建成分的代號，直接用換算出來的成本
      // 補一筆進商品清單（名稱因為沒有商品總表可抓，用成分品名拼起來；品牌用代號前綴猜，見
      // config.js 的 getBrandByCode）。標記 virtualBundle:true，庫存管理頁會把這種補進來的列濾掉——
      // 這種代號本來就只是「組合」，沒有獨立的庫存/安全庫存欄位可管理，不是漏填庫存。
      const brandByCode = {};
      products.forEach(p => { brandByCode[p.code] = p.brand; });
      Object.keys(bundleCost).forEach(code => {
        if (existingCodes.has(code)) return;
        const comps = bundleComponents[code] || [];
        const name = comps.length
          ? comps.map(c => (c.qty > 1 ? `${c.name}×${c.qty}` : c.name)).join('+')
          : code;
        // 品牌：看組成這個套組的單品屬於哪個品牌（例如 NEW499LN 的成分是麗容酵素的商品），
        // 不是只看代號前綴——之前用前綴猜，NEW 開頭的代號一律被猜成 TOOLA。
        const compBrand = comps.map(c => brandByCode[c.code]).find(Boolean);
        products.push({
          code,
          brand: compBrand || normalizeBrand('', code),
          components: comps,
          name,
          barcode: '',
          u: 1,
          cost: bundleCost[code],
          stock: 0,
          safety: 0,
          sold: 0,
          virtualBundle: true, // 只存在於套組成分表，商品總表沒有這一列
        });
      });

      return products;
    } catch(e) { console.warn('readProducts error:', e.message); return []; }
  }, [read]);

  // ── 讀取「平台代號對應表」：各平台的亂碼代號 → 商品總表標準代號 ──────────
  // 2026-10-23 新增：Willie 回報銷貨總表上一堆代號顯示「查無資料」，查出來發現部分是
  // momo 報表上用的代號其實是 momo 自己的商品編號（例如「8233476」），不是商品總表
  // 用的標準代號（例如「BDLN101」）。Sheet 裡本來就有維護這張「平台代號對應表」做轉換，
  // 但 App 一直沒有讀它，所以這種代號永遠對不到商品總表的成本，一律顯示查無資料
  // （詳見 10/11 第十五次更新稽核時的發現）。這裡讀出來做成 {原始代號: 標準代號} 的
  // 對照表，SalesPage.js／Dashboard.js／PnlPage.js 在拿平台報表上的代號去查 costMap
  // 之前，會先用這張表轉換一次，轉換不到的代號維持原樣（可能本來就是標準代號）。
  // 表格第4、5列是 Willie 當初建這張表時填的「示範」列（備註欄會寫「示範」兩個字），
  // 不是真實的對應資料，讀取時會跳過，避免拿示範資料去蓋掉其他列真正的對應關係。
  const readCodeMap = useCallback(async () => {
    try {
      const rows = await read('平台代號對應表!A4:E');
      const map = {};
      (rows || []).forEach(r => {
        const raw  = String(r[1] || '').trim();
        const std  = String(r[2] || '').trim();
        const note = String(r[4] || '').trim();
        if (!raw || !std) return;
        if (note.includes('示範')) return; // 跳過範例列，不是真實資料
        // 數字代號 Google Sheets 可能讀成浮點數字串（例如 "8233476.0"），這裡去掉多餘的小數部分，
        // 跟平台報表實際寫入的字串（純數字、沒有小數點）對得起來。
        const normalizedRaw = raw.replace(/\.0+$/, '');
        map[normalizedRaw] = std;
      });
      return map;
    } catch(e) { console.warn('readCodeMap error:', e.message); return {}; }
  }, [read]);


  // ── 讀取各平台原始資料 ───────────────────────────────────────
  // 注意：範圍故意寫成「A2:Z」不指定結尾列號（之前是寫死 A2:Z5000）。
  // Google Sheets API 遇到沒寫列號的範圍，會自動讀到那個分頁「實際有資料的最後一列」，
  // 不用自己猜要留多少空間。之前寫死 5000 列，等於幫每個平台報表的歷史資料設了一個
  // 隱形的天花板，資料量成長到超過這個數字時，最舊的一批資料會被讀取範圍直接排除在外，
  // 而且不會有任何錯誤訊息，銷貨總表/首頁的數字會悄悄漏掉一段歷史，完全不會發現。
  // 商品總表、套組成分表、customers、orders、accounts、materials、損益表 也是同樣邏輯，
  // 已經一併從「寫死列數」改成不指定結尾列號。
  const readPlatformData = useCallback(async (sheetName) => {
    try {
      const rows = await read(`${sheetName}!A2:Z`);
      return rows.filter(isDataRow); // 跳過標題列/說明列/欄名列（見上方 isDataRow 說明）
    } catch(e) { return []; }
  }, [read]);

  // 跟 readPlatformData 一樣，但讀取失敗時會丟出錯誤（不會回傳空陣列）。
  // 報表上傳「比對有沒有重複」一定要用這個：如果讀取失敗卻當成「Sheets 裡沒有資料」，
  // 就會把已經上傳過的資料再寫一次，營收變成重複計算。
  const readPlatformDataStrict = useCallback(async (sheetName) => {
    const rows = await read(`${sheetName}!A2:Z`);
    return rows.filter(isDataRow);
  }, [read]);

  // ── 讀取所有銷售資料（合併各平台）────────────────────────────
  const readAllSales = useCallback(async () => {
    try {
      const [shopline, momo, shopee, erp, orders] = await Promise.all([
        readPlatformData('shopline_raw'),
        readPlatformData('momo_raw'),
        readPlatformData('shopee_raw'),
        readPlatformData('erp_raw'),
        readPlatformData('orders'),
      ]);
      return { shopline, momo, shopee, erp, orders };
    } catch(e) { return { shopline:[], momo:[], shopee:[], erp:[], orders:[] }; }
  }, [readPlatformData]);

  // ── 寫入/讀取損益表費用（廣告費、其他營業費用）──────────────────
  // ⚠ 2026-10-02 重大修正：之前存檔完全沒有記錄「這是哪一個月的費用」，
  // 讀取的時候永遠是拿「最後一次存檔的那一筆」套用到畫面上——不管切到哪個月，
  // 看到的廣告費/其他費用輸入框都是同一組數字。這是錯的：廣告費、其他營業費用
  // 本來就是每個月各自不同、要分別手動輸入的金額，不能讓上個月存的數字自動
  // 套用到這個月（或任何還沒輸入過的月份）。
  // 已改成存檔時一併記錄「年-月」，讀取時回傳「每個月各自的費用」整包資料
  // （一個以年月為 key 的物件），由畫面自己挑出目前選的那個月，沒存過的月份
  // 就是空白（0），逼使用者針對那個月重新輸入真實數字，不會被其他月份的舊數字帶過去。
  // customExpenses：使用者自己新增的費用名稱清單（不是 EXPENSE_ITEMS 那組固定項目），
  // 格式 [{ name, amount, note }, ...]，跟 adCost/expenses 一樣整包存成 JSON 字串，
  // 放在第5欄（E），不影響前4欄舊資料的讀取方式。
  //
  // ⚠ 2026-10-11 重大修正：這裡原本是寫進「損益表」這個分頁——但「損益表」其實是
  // Willie 自己維護的「自動產出」原生公式報表（年度/月份選擇器＋項目/說明/金額/備註
  // 的格式化表格），不是一張空白的資料表。Google Sheets API 的 append 預設行為是
  // 「INSERT_ROWS」：每次存檔都會在找到的最後一列資料後面「插入新的一列」，把下面
  // 原本的內容整列往下推——不是單純接在資料表最後面。因為「損益表」分頁裡本來就有
  // Willie 的原生報表內容佔著 A~E 欄，每次這裡存檔，都會把一列「日期＋JSON亂碼」
  // 插進那個原生報表的中間，把下面的列往下推一列。直接讀 Sheets 後台核對過，
  // 「損益表」分頁裡已經混雜了一堆這種存檔列（在原生報表的「一、銷貨收入」「三、毛利」
  // 等標題中間），這代表原生報表的列已經被这些存檔動作往下推了好幾次，原本設計的格式
  // 很可能已經跟 Willie 當初排的不一樣了。
  // 已修正：改成寫進一個全新、專門給這個功能用的分頁「pnl_expenses」，跟「損益表」
  // 原生報表完全分開，不會再互相干擾。
  // ⚠ 2026-10-22 補充：10/11 版本部署後，Willie 回報存檔時出現「Unable to parse
  // range: pnl_expenses!A2」的錯誤——原因是部署時忘記先手動建立這個分頁。已經改用
  // 下面的 appendRawEnsureSheet，存檔失敗時會自動偵測「分頁不存在」並自動補建，
  // 不再需要 Willie 自己先手動建立分頁。
  const PNL_EXPENSES_SHEET = 'pnl_expenses';
  const savePnlData = useCallback(async (year, month, adCost, expenses, customExpenses) => {
    try {
      const ym = `${year}-${String(month).padStart(2, '0')}`;
      const row = [
        new Date().toLocaleDateString('zh-TW'),
        ym,
        JSON.stringify(adCost),
        JSON.stringify(expenses),
        JSON.stringify(customExpenses || []),
      ];
      await appendRawEnsureSheet(PNL_EXPENSES_SHEET, `${PNL_EXPENSES_SHEET}!A2`, [row]);
      return { ok:true };
    } catch(e) {
      console.warn('savePnlData failed:', e.message);
      return { ok:false, error:`寫入 Google Sheets 失敗：${e.message}，這個月的廣告費/費用沒有存成功` };
    }
  }, [appendRawEnsureSheet]);

  // 回傳格式：{ "2026-09": { adCost:{...}, expenses:{...}, customExpenses:[...] }, "2026-10": {...}, ... }
  const loadPnlData = useCallback(async () => {
    try {
      const rows = await read(`${PNL_EXPENSES_SHEET}!A2:E`);
      if (!rows || rows.length === 0) return {};
      const byMonth = {};
      rows.forEach(r => {
        const ym = r[1];
        // 只認「YYYY-MM」格式的年月標記；舊版沒有記錄年月的資料（這一欄剛好放的是
        // 舊格式的 JSON 字串，不會符合這個格式）直接跳過，不會被誤套用到任何月份。
        if (!/^\d{4}-\d{2}$/.test(ym || '')) return;
        try {
          byMonth[ym] = {
            adCost:         r[2] ? JSON.parse(r[2]) : {},
            expenses:       r[3] ? JSON.parse(r[3]) : {},
            customExpenses: r[4] ? JSON.parse(r[4]) : [], // 舊資料沒有這一欄，預設空陣列
          };
        } catch(e) { /* 這筆存檔資料壞掉就跳過，不影響其他月份 */ }
      });
      return byMonth; // 同一個月存過好幾次時，後面的列會蓋掉前面的，自然就是「那個月最新一次」
    } catch(e) { return {}; }
  }, [read]);

  // ── 「本月無銷貨資料」標記（2026-10-22 新增）────────────────────
  // 報表上傳頁可以幫每個賣場標記「這個月真的沒有銷貨」，標記過的賣場就不會再一直
  // 顯示「待上傳」（見 utils/salesCalc.js 的 computeUploadStatus 的 markers 參數）。
  // 存進一個新的分頁「no_sales_marker」，每一列是 [賣場ID, 月份(YYYY-MM), 標記時間]。
  // 用 appendRawEnsureSheet，Willie 不需要手動先建這個分頁——分頁不存在時會自動補建。
  const NO_SALES_SHEET = 'no_sales_marker';
  const markNoSales = useCallback(async (storeId, year, month) => {
    try {
      const ym = `${year}-${String(month).padStart(2, '0')}`;
      const row = [storeId, ym, new Date().toLocaleDateString('zh-TW')];
      await appendRawEnsureSheet(NO_SALES_SHEET, `${NO_SALES_SHEET}!A2`, [row]);
      return { ok:true };
    } catch(e) {
      console.warn('markNoSales failed:', e.message);
      return { ok:false, error:`標記失敗：${e.message}` };
    }
  }, [appendRawEnsureSheet]);

  const readNoSalesMarkers = useCallback(async () => {
    try {
      const rows = await read(`${NO_SALES_SHEET}!A2:C`);
      return (rows || []).filter(r => r[0] && r[1]).map(r => ({ storeId: r[0], ym: r[1] }));
    } catch(e) { return []; }
  }, [read]);

  return { read, append, clear, writePlatformData, readExpenses, writeExpenses, readCustomers, writeCustomer, updateCustomer, writeOrder, readOrders, readOrdersGrouped, deleteOrder, updateOrder, updateInventory, writeNewProduct, readAccounts, writeAccount, updateAccount, readProducts, readMaterials, writeMaterial, updateMaterial, readPlatformData, readPlatformDataStrict, readAllSales, savePnlData, loadPnlData, markNoSales, readNoSalesMarkers, readCodeMap };
}
