import { useState, useRef, useCallback, useEffect } from 'react';
import { Upload, CheckCircle, AlertCircle, X, Eye } from 'lucide-react';
import { autoParsePlatform } from '../utils/excelParser';
import { fmt, PLATFORM_COLORS, getCurrentYM, getPreviousYM } from '../utils/format';
import { useSheets } from '../hooks/useSheets';
import { STORES, PLATFORM_STORES, getStoreName } from '../utils/config';
import { computeUploadStatus } from '../utils/salesCalc';

const PLATFORMS = ['官網','momo','蝦皮','經銷'];

function StoreSelector({ platform, value, onChange }) {
  const options = (PLATFORM_STORES[platform] || []).map(id => STORES.find(s => s.id === id)).filter(Boolean);
  if (options.length <= 1) return null;
  return (
    <div style={{ marginTop:10 }}>
      <label className="form-label">這份報表是哪個賣場？</label>
      <div style={{ display:'flex', gap:8, flexWrap:'wrap', marginTop:6 }}>
        {options.map(s => (
          <button key={s.id}
            className={`btn btn-sm ${value===s.id ? 'btn-primary' : 'btn-ghost'}`}
            style={ value===s.id ? { borderColor:s.color, color:s.color, background:`${s.color}15`, boxShadow:`0 0 8px ${s.color}30` } : {} }
            onClick={() => onChange(s.id)}>
            {s.name}
          </button>
        ))}
      </div>
    </div>
  );
}

function FileCard({ result, onRemove, onConfirm, confirming }) {
  const [showPreview, setShowPreview] = useState(false);
  const [storeId, setStoreId] = useState(() => {
    const opts = PLATFORM_STORES[result.platform] || [];
    return opts.length === 1 ? opts[0] : '';
  });
  const color = PLATFORM_COLORS[result.platform] || '#00f5ff';
  const preview = (result.rows || []).slice(0, 5);
  const needsStore = (PLATFORM_STORES[result.platform] || []).length > 1;
  // momo「廠商進貨彙整表」（格式B）報表本身沒有任何日期，之前上傳後永遠歸不到任何月份
  // （首頁/損益表選月份時 momo 這部分一直是 0），而且同一份報表重複上傳也分不出來。
  // 2026-10-25 起上傳這種報表時要先選「這是哪個月份的報表」，整份資料記在那個月。
  const needsMonth = result.platform === 'momo' && result.summary?.format === 'B';
  const [month, setMonth] = useState(() => {
    const p = getPreviousYM();
    return `${p.year}-${String(p.month).padStart(2,'0')}`;
  });
  const canConfirm = (!needsStore || storeId) && (!needsMonth || /^\d{4}-\d{2}$/.test(month));

  return (
    <div className="card mt-12" style={{ borderLeft:`3px solid ${color}`, boxShadow:`0 0 12px ${color}15` }}>
      <div className="flex-between">
        <div className="flex-center gap-8">
          <div style={{ width:32, height:32, borderRadius:3, display:'flex', alignItems:'center', justifyContent:'center', background:`${color}18`, fontSize:14, fontWeight:700, color, border:`1px solid ${color}40`, letterSpacing:1 }}>
            {result.platform}
          </div>
          <div>
            <div style={{ fontSize:18, fontWeight:600, color:'var(--text)', letterSpacing:1 }}>{result.filename}</div>
            <div style={{ fontSize:14, color:'var(--muted)', marginTop:2 }}>
              {result.summary?.count} 筆有效資料 ·
              銷售金額 <span style={{ color:'var(--cyan)' }}>{fmt.currency(result.summary?.revenue)}</span>
              {storeId && <span style={{ marginLeft:8, color:'var(--yellow)' }}>▸ {getStoreName(storeId)}</span>}
            </div>
          </div>
        </div>
        <div className="flex-center gap-8">
          <button className="btn btn-ghost btn-sm" onClick={() => setShowPreview(v => !v)}>
            <Eye size={13}/> {showPreview ? '收起' : '預覽'}
          </button>
          {!result.confirmed
            ? <button className="btn btn-primary btn-sm"
                onClick={() => onConfirm(result, storeId, needsMonth ? month : null)}
                disabled={confirming || !canConfirm}
                title={!canConfirm ? (needsMonth ? '請先選擇報表月份' : '請先選擇賣場') : ''}>
                {confirming ? '存入中…' : canConfirm ? '◈ 確認匯入' : (needsMonth ? '請先選擇月份' : '請先選擇賣場')}
              </button>
            : <span className="badge badge-ok"><CheckCircle size={11}/> 已匯入</span>
          }
          <X size={14} style={{ cursor:'pointer', color:'var(--muted)' }} onClick={() => onRemove(result.id)}/>
        </div>
      </div>

      {/* 賣場選擇（蝦皮/官網才會出現） */}
      {!result.confirmed && (
        <StoreSelector platform={result.platform} value={storeId} onChange={setStoreId}/>
      )}
      {!result.confirmed && needsMonth && (
        <div style={{ marginTop:10 }}>
          <label className="form-label">這份 momo 彙整報表是哪個月份的？（報表本身沒有日期，整份會記在這個月）</label>
          <input className="form-input" type="month" style={{ maxWidth:200, marginTop:6 }}
            value={month} onChange={e => setMonth(e.target.value)}/>
        </div>
      )}
      {result.confirmed && (
        <div style={{ marginTop:8, fontSize:14, color:'var(--green)', letterSpacing:1, lineHeight:1.7 }}>
          ✓ 已匯入{result.storeId ? `至賣場：${getStoreName(result.storeId)}` : ''}{result.month ? `（${result.month}）` : ''}
          　新增 {result.newCount} 筆
          {result.dupeCount > 0 && (
            <span style={{ color:'var(--yellow)' }}>，略過 {result.dupeCount} 筆（Google Sheets 裡已經有一模一樣的資料，判定為重複上傳）</span>
          )}
        </div>
      )}

      {showPreview && preview.length > 0 && (
        <div className="table-wrap mt-12">
          <table>
            <thead><tr>{preview[0].map((_, i) => <th key={i}>欄 {i+1}</th>)}</tr></thead>
            <tbody>
              {preview.map((row, i) => (
                <tr key={i}>{row.map((cell, j) => (
                  <td key={j} className="td-mono" style={{ maxWidth:140, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', fontSize:14 }}>
                    {String(cell || '–')}
                  </td>
                ))}</tr>
              ))}
            </tbody>
          </table>
          {result.rows.length > 5 && (
            <div style={{ fontSize:14, color:'var(--muted)', padding:'6px 0', textAlign:'right', letterSpacing:1 }}>
              顯示前 5 筆，共 {result.rows.length} 筆
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default function UploadPage() {
  const [files, setFiles]           = useState([]);
  const [dragging, setDragging]     = useState(false);
  const [parsing, setParsing]       = useState(false);
  const [confirming, setConfirming] = useState(null);
  const [error, setError]           = useState('');
  const inputRef = useRef();

  // 賣場狀態改成直接看 Sheets 裡的真實資料，不是「這個瀏覽器分頁這次有沒有上傳過」——
  // 之前這裡的狀態只看 files（這次畫面上的檔案清單），重新整理網頁、或分批上傳到一半
  // 換分頁/換人操作，都會讓已經匯入過的賣場又顯示「待上傳」，其實 Sheets 裡資料都在。
  const { readAllSales, readNoSalesMarkers, markNoSales } = useSheets();
  const [realStatus, setRealStatus] = useState({});
  // 右上角月份切換——預設看當月（這裡是上傳報表的地方，通常是在幫當月補資料），
  // 但使用者也可能需要回頭檢查上個月是否有遺漏，所以開放切換。
  const [ym, setYm] = useState(() => getCurrentYM());
  const shiftMonth = (delta) => {
    setYm(p => {
      let m = p.month + delta, y = p.year;
      if (m < 1) { m = 12; y -= 1; }
      if (m > 12) { m = 1; y += 1; }
      return { year:y, month:m };
    });
  };
  // 同時撈「本月無銷貨資料」的標記，傳給 computeUploadStatus，標記過的賣場
  // 就不會再一直顯示「待上傳」（見下方「本月無銷貨資料」按鈕）。
  const loadStatus = useCallback(() => {
    return Promise.all([readAllSales(), readNoSalesMarkers()])
      .then(([sales, markers]) => {
        const markerSet = new Set((markers || []).map(m => `${m.storeId}|${m.ym}`));
        setRealStatus(computeUploadStatus(sales, ym.year, ym.month, markerSet));
      }).catch(() => {});
  }, [readAllSales, readNoSalesMarkers, ym]);
  useEffect(() => { loadStatus(); }, [loadStatus]);

  const handleMarkNoSales = useCallback(async (storeId) => {
    const res = await markNoSales(storeId, ym.year, ym.month);
    if (res && res.ok === false) { setError(res.error); return; }
    loadStatus();
  }, [markNoSales, ym, loadStatus]);

  const processFiles = useCallback(async (fileList) => {
    setParsing(true); setError('');
    for (const file of Array.from(fileList)) {
      try {
        const result = await autoParsePlatform(file);
        if (!result.platform) { setError(`無法辨識「${file.name}」的平台格式`); continue; }
        setFiles(prev => [...prev, { ...result, filename:file.name, id:Date.now()+Math.random(), confirmed:false }]);
      } catch (e) { setError(`解析「${file.name}」失敗：${e.message}`); }
    }
    setParsing(false);
  }, []);

  const { writePlatformData, readPlatformDataStrict } = useSheets();

  // ── 確認匯入 ────────────────────────────────────────────────
  // ⚠ 2026-10-25 重寫「去除重複」：之前只跟「這個瀏覽器分頁這次上傳過的檔案」比對
  // （存在瀏覽器記憶體裡），重新整理網頁、換一台電腦、隔天再上傳，都完全不會比對到
  // Google Sheets 裡已經有的資料——實際檢查 Sheets 後台，官網 8 月的報表就被上傳了兩次
  // （shopline_raw 裡同樣的 175 列出現兩份），8 月官網營收被重複算了一倍。
  // 現在改成：匯入前先把 Google Sheets 那個分頁目前的資料讀出來，用「訂單編號＋代號＋
  // 數量＋金額＋賣場」等欄位組成識別碼比對，Sheets 裡已經有一模一樣的列就略過。
  // 只跟 Sheets 既有資料比對，不跟同一份檔案裡的其他列比對——同一張訂單裡本來就可能
  // 有兩列完全一樣的品項（例如兩個 0 元贈品），那是真的資料，不能被當成重複刪掉。
  // 如果讀取 Sheets 失敗，直接停止匯入，不會在「不知道有沒有重複」的情況下硬寫進去。
  const KEY_COLS = {
    shopline_raw: [0, 4, 5, 7],    // 訂單號碼, 代號, 數量, 付款總金額
    shopee_raw:   [0, 2, 4, 6],    // 訂單編號, 代號, 數量, 買家總支付金額
    momo_raw:     [0, 1, 2, 4, 5], // 編號, 日期, 代號, 數量, 進價
    erp_raw:      [0, 2, 3, 5, 6], // 客戶代號, 日期, 代號, 數量, 含稅金額
  };
  const normKeyPart = (v) => {
    const t = String(v ?? '').trim();
    const n = Number(t.replace(/,/g, ''));
    return t !== '' && !isNaN(n) ? String(n) : t; // 「1」「1.0」「1,000」這種格式差異視為相同
  };

  const handleConfirm = useCallback(async (result, storeId, month) => {
    setConfirming(result.id);
    try {
      const sheetMap = {
        'TOOLA_SHOPLINE': 'shopline_raw',
        'TOOLA_SHOPEE':   'shopee_raw',
        'MOMO':           'momo_raw',
        'TAKUYA_SHOPEE':  'shopee_raw',
        'TAKUYA_SHOPLINE':'shopline_raw',
        'ERP':            'erp_raw',
        'momo':           'momo_raw',
        'shopee':         'shopee_raw',
        'shopline':       'shopline_raw',
        'erp':            'erp_raw',
        '官網':           'shopline_raw',
        '蝦皮':           'shopee_raw',
        '經銷':           'erp_raw',
      };
      const sheetName = sheetMap[storeId] || sheetMap[result.platform];
      if (!sheetName) throw new Error(`不知道這份報表要寫到哪個分頁（平台：${result.platform}）`);
      const storeTag = storeId || result.platform;

      // momo 格式B：套用使用者選的月份（日期記成那個月的1號），編號也加上月份，
      // 不同月份的彙整報表才不會被誤判成同一筆。
      let rows = result.rows;
      if (month) {
        rows = rows.map(r => {
          const nr = [...r];
          nr[0] = String(nr[0]).replace(/^MOMO-/, `MOMO-${month}-`);
          nr[1] = `${month}-01`;
          return nr;
        });
      }
      const rowsWithStore = rows.map(row => [...row, storeTag]);

      const cols = KEY_COLS[sheetName];
      const keyOf = (r, tag) => cols.map(i => normKeyPart(r[i])).join('|') + '|' + tag;
      const existing = await readPlatformDataStrict(sheetName);
      const existingKeys = new Set(existing.map(r => keyOf(r, String(r[r.length - 1] || '').trim())));
      const newRows = rowsWithStore.filter(r => !existingKeys.has(keyOf(r, storeTag)));
      const dupeCount = rowsWithStore.length - newRows.length;

      if (newRows.length > 0) await writePlatformData(sheetName, newRows);

      setFiles(prev => prev.map(f => f.id === result.id
        ? { ...f, confirmed:true, storeId, month, dupeCount, newCount:newRows.length }
        : f
      ));
      // 寫入成功後重新讀一次 Sheets，讓上面的「賣場狀態」立刻反映真實資料，不用等重新整理網頁。
      loadStatus();
    } catch(e) {
      setError(`匯入失敗：${e.message}。這份報表沒有寫進 Google Sheets（或只寫入一部分），請確認網路/登入狀態後再試一次。`);
    }
    setConfirming(null);
  }, [writePlatformData, readPlatformDataStrict, loadStatus]); // eslint-disable-line

  return (
    <div>
      {/* 賣場狀態 —— 直接看 Sheets 裡的真實資料，不是這次瀏覽器分頁上傳過的檔案清單 */}
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:10 }}>
        <div style={{ fontSize:13, color:'var(--muted)' }}>賣場上傳狀態</div>
        <div style={{ display:'flex', alignItems:'center', gap:8 }}>
          <button className="btn btn-sm btn-ghost" onClick={() => shiftMonth(-1)}>‹</button>
          <span style={{ fontSize:14, color:'var(--text)', minWidth:78, textAlign:'center', fontFamily:'var(--mono)' }}>
            {ym.year}年{ym.month}月
          </span>
          <button className="btn btn-sm btn-ghost" onClick={() => shiftMonth(1)}>›</button>
        </div>
      </div>
      <div style={{ display:'grid', gridTemplateColumns:'repeat(2,1fr)', gap:10, marginBottom:16 }}>
        {STORES.map(s => {
          const st = realStatus[s.id] || {};
          const done = st.done;
          return (
            <div key={s.id} className={`platform-chip${done ? ' done' : ''}`}>
              <div className="platform-dot" style={{ background: done ? s.color : 'var(--muted)', boxShadow: done ? `0 0 6px ${s.color}` : 'none' }}/>
              <div className="platform-chip-info">
                <div className="platform-chip-name" style={{ color: done ? s.color : 'var(--text)' }}>{s.name}</div>
                <div className="platform-chip-status" style={!done ? {color:'var(--yellow)'} : {}}>
                  {done
                    ? (st.noSalesMarked ? '－ 本月無銷貨資料' : st.approximate ? `✓ 有上傳過（無日期，無法確認是否為${ym.year}年${ym.month}月）` : '✓ 已匯入')
                    : `⚠ ${s.platform} · 待上傳`}
                </div>
                {/* 這個月真的沒有銷貨時可以按這個，就不會一直顯示「待上傳」 */}
                {!done && (
                  <button className="btn btn-ghost btn-sm" style={{ marginTop:4, fontSize:12, padding:'2px 8px' }}
                    onClick={() => handleMarkNoSales(s.id)}>
                    本月無銷貨資料
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* 拖曳區 */}
      <div
        className={`upload-zone${dragging ? ' drag-over' : ''}`}
        onDragOver={e => { e.preventDefault(); setDragging(true); }}
        onDragLeave={() => setDragging(false)}
        onDrop={e => { e.preventDefault(); setDragging(false); processFiles(e.dataTransfer.files); }}
        onClick={() => inputRef.current?.click()}
      >
        <input ref={inputRef} type="file" accept=".xlsx,.xls" multiple hidden onChange={e => processFiles(e.target.files)}/>
        <div className="upload-zone-icon">
          {parsing ? <div className="spinner" style={{ width:32, height:32, margin:'0 auto' }}/> : <Upload size={32}/>}
        </div>
        <h3>{parsing ? '解析中…' : '拖曳 Excel 至此，或點擊選擇'}</h3>
        <p>支援 .xlsx / .xls · 自動辨識<strong> 官網、momo、蝦皮、經銷 </strong>格式</p>
        <p style={{ marginTop:8, fontSize:17, color:'var(--yellow)' }}>⚠ 蝦皮和官網上傳後需選擇賣場（TOOLA / 拓屋）</p>
        <p style={{ marginTop:4, fontSize:14, color:'var(--muted)' }}>◈ 匯入前會先比對 Google Sheets 裡已經有的資料，同一份報表重複上傳、或分批上傳有重疊，重複的部分會自動略過</p>
      </div>

      {/* 錯誤訊息 */}
      {error && (
        <div style={{ display:'flex', alignItems:'center', gap:8, background:'rgba(255,0,110,0.08)', border:'1px solid rgba(255,0,110,0.3)', borderRadius:3, padding:'10px 14px', marginTop:12, fontSize:17, color:'var(--pink)' }}>
          <AlertCircle size={14}/> {error}
          <X size={12} style={{ marginLeft:'auto', cursor:'pointer' }} onClick={() => setError('')}/>
        </div>
      )}

      {/* 檔案卡片 */}
      {files.map(result => (
        <FileCard key={result.id} result={result}
          onRemove={id => setFiles(prev => prev.filter(f => f.id !== id))}
          onConfirm={handleConfirm}
          confirming={confirming === result.id}
        />
      ))}

      {/* 說明 */}
      <div className="card mt-20" style={{ background:'rgba(0,245,255,0.02)', border:'1px solid var(--border)' }}>
        <div className="card-title">各賣場報表說明</div>
        <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12, fontSize:14 }}>
          {[
            { name:'TOOLA 官網 / 拓屋 官網', tip:'Shopline 後台 → 訂單管理 → 匯出 Sales 報表', note:'上傳後選擇對應賣場' },
            { name:'TOOLA 蝦皮 / 拓屋 蝦皮', tip:'賣場中心 → 訂單 → 匯出已完成訂單（Order_completed）', note:'上傳後選擇對應賣場' },
            { name:'momo', tip:'廠商後台 → 訂單 → 廠商出貨報表（有訂單編號、日期的明細最好）', note:'如果上傳的是沒有日期的「廠商進貨彙整表」，會請你選這份報表是哪個月份' },
            { name:'經銷 ERP', tip:'ERP → 銷貨明細表(客戶)（含銷退）', note:'日期直接用報表上每一筆的銷退貨日期' },
          ].map(({ name, tip, note }) => (
            <div key={name} style={{ padding:12, background:'var(--bg3)', borderRadius:3, border:'1px solid var(--border)' }}>
              <div style={{ fontWeight:700, color:'var(--cyan)', marginBottom:6, letterSpacing:1, fontSize:14 }}>{name}</div>
              <div style={{ color:'var(--text)', marginBottom:6, lineHeight:1.6 }}>{tip}</div>
              <div style={{ color:'var(--yellow)', fontSize:17, marginTop:4 }}>⚠ {note}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}